// Body enviado por el Custom Webhook de GHL (ver docs/ghl-setup.md).
const webhook = $('Webhook').first().json;
const body = webhook.body || {};
const headers = webhook.headers || {};
const clean = (value) => (typeof value === 'string' ? value.trim() : '');
// `action` puede venir en el body o como header (n8n recibe los headers en minúsculas).
const rawAction = clean(body.action || headers.action || headers['x-action']).toLowerCase();
const action = ['amend', 'anexo', 'ajuste', 'modificar'].includes(rawAction) ? 'amend' : 'create';
return [{
  json: {
    action,
    locationId: clean(body.locationId),
    contactId: clean(body.contactId),
    contactName: clean(body.contactName),
    contactPhone: clean(body.contactPhone),
    // Opcional: la fuente principal es la conversación; el resumen del agente solo ayuda.
    resumen: clean(body.resumen),
  },
}];

// No dependemos de que el agente llene bien un campo: leemos lo que realmente se habló.
const input = $('Normalizar entrada').first().json;
const response = $input.first().json;
const raw = response.body?.messages;
// GHL responde { messages: { messages: [...] } }; se aceptan también listas planas.
const messages = Array.isArray(raw) ? raw : Array.isArray(raw?.messages) ? raw.messages : [];

const turns = messages
  .filter((message) => typeof message.body === 'string' && message.body.trim())
  .sort((a, b) => new Date(a.dateAdded || 0) - new Date(b.dateAdded || 0))
  .map((message) => `${message.direction === 'inbound' ? 'CLIENTE' : 'FRUTITODO'}: ${message.body.trim()}`);

const lastMessageId = messages
  .slice()
  .sort((a, b) => new Date(b.dateAdded || 0) - new Date(a.dateAdded || 0))[0]?.id || '';

return [{
  json: {
    transcript: turns.join('\n'),
    turns: turns.length,
    readStatus: response.statusCode,
    // Idempotencia: el mismo último mensaje del mismo contacto es el mismo pedido.
    idempotencySeed: `${input.contactId}|${input.action}|${lastMessageId || input.resumen}`,
  },
}];

