parameters.jsCode:
const input = $('Normalizar entrada').first().json;
const response = $input.first().json;
const conversation = $('Buscar conversación GHL').first().json;
const conversationId = conversation?.body?.conversations?.[0]?.id || null;

let extracted = null;
let problem = null;
if (response.statusCode !== 200) {
  problem = `OpenAI respondió ${response.statusCode}`;
} else {
  try {
    extracted = JSON.parse(response.body?.choices?.[0]?.message?.content || 'null');
  } catch (error) {
    problem = 'La respuesta del modelo no es JSON válido';
  }
}

const transcript = $('Armar transcripción').first().json;
if (!transcript.turns && !input.resumen) problem = `No se pudieron leer los mensajes de la conversación (GHL respondió ${transcript.readStatus})`;
if (!problem && extracted && !extracted.ok) problem = extracted.error || 'La conversación no contiene un pedido';
const items = (extracted?.items || [])
  .map((item) => ({
    name: String(item.name || '').trim(),
    quantity: Number(item.quantity),
    ...(item.unit ? { unit: String(item.unit).trim() } : {}),
  }))
  .filter((item) => item.name && item.quantity > 0);
if (!problem && !items.length) problem = 'El pedido no tiene productos con cantidad';

const name = (extracted?.customer?.name || input.contactName || '').trim();
const phone = (extracted?.customer?.phone || input.contactPhone || '').trim();
if (!problem && !name) problem = 'Falta el nombre del cliente';
if (!problem && phone.length < 3) problem = 'Falta el teléfono del cliente';
const delivery = extracted?.delivery?.type === 'recogida'
  ? { type: 'recogida' }
  : { type: 'domicilio', address: (extracted?.delivery?.address || '').trim() };
if (!problem && delivery.type === 'domicilio' && !delivery.address) problem = 'Falta la dirección del domicilio';

// Resumen legible que se guarda de vuelta en GHL (campo pedido_resumen).
const summaryText = [
  `Cliente: ${name}${extracted?.customer?.document ? ` | Cédula: ${extracted.customer.document}` : ''} | Tel: ${phone}`,
  delivery.type === 'recogida' ? 'Entrega: Recoge en tienda' : `Entrega: Domicilio – ${delivery.address}`,
  extracted?.paymentMethod ? `Pago: ${extracted.paymentMethod}` : null,
  'Productos:',
  ...items.map((item) => `- ${item.quantity}${item.unit ? ` ${item.unit}` : ''} ${item.name}`),
  extracted?.notes ? `Observaciones: ${extracted.notes}` : null,
].filter(Boolean).join('\n');

return [{
  json: {
    valid: !problem,
    problem,
    action: input.action,
    conversationId,
    idempotencySeed: transcript.idempotencySeed,
    summaryText,
    payload: {
      locationId: input.locationId,
      contactId: input.contactId,
      conversationId: conversationId || undefined,
      customer: { name, phone, document: extracted?.customer?.document || undefined },
      delivery,
      paymentMethod: extracted?.paymentMethod || undefined,
      items,
      notes: extracted?.notes || undefined,
    },
  },
}];

const response = $input.first().json;
const status = response.statusCode;
const body = response.body || {};
const ok = status >= 200 && status < 300 && Boolean(body.order?.number);
// Un ajuste conserva el número: es el mismo pedido, no uno nuevo.
const adjusted = ok && body.amended !== undefined;
return [{
  json: {
    ok,
    status,
    adjusted,
    orderNumber: body.order?.number || null,
    duplicate: Boolean(body.duplicate),
    error: ok ? null : (body.message || `La app respondió ${status}`),
  },
}];

parameters.jsonBody:
={{ (() => {
  const cfg = $('Config').item.json;
  const p = $('Validar extracción').item.json.payload;
  const r = $('Resultado').item.json;
  const fields = [
    [cfg.CF_ULTIMO_PEDIDO_NUMERO, r.orderNumber],
    [cfg.CF_ULTIMO_PEDIDO_ESTADO, 'nuevo'],
    [cfg.CF_PEDIDO_RESUMEN, $('Validar extracción').item.json.summaryText],
    [cfg.CF_CEDULA, p.customer.document],
    [cfg.CF_METODO_PAGO, p.paymentMethod],
    [cfg.CF_DIRECCION, p.delivery.type === 'domicilio' ? p.delivery.address : null],
  ].filter(([key, value]) => key && value);
  const body = { customFields: fields.map(([key, value]) => ({ key, field_value: value })) };
  if (p.delivery.type === 'domicilio') body.address1 = p.delivery.address;
  return JSON.stringify(body);
})() }}
